import random

from routellm.dataset.verbalization.styles import get_style
from routellm.dataset.verbalization.tasks import BaseTask


class LongDescriptionTask(BaseTask):
    NAME = "llm-tasks.long-description"
    VERSION = 6
    TASK_LIST = [
        "Give a very long and very detailed description (at least 10 sentences) of the following route:",
        "Hey, can you give me a long description of this route?",
        "Can you provide an extensive and comprehensive account of this route?",
        "Please provide a thorough and in-depth description of the route, covering all the nuances:",
        "I'm interested in a long and detailed description of this route:",
        "Give a complete and detailed summary of this route:",
    ]

    def get_task(self):
        return random.choice(LongDescriptionTask.TASK_LIST)

    def get_system_message(self, style_info=None):
        system_message = "You are an AI that answers questions about routes. Take a deep breath and do it step by step. Use at least 10 sentences!"

        if style_info is None:
            style_text, style = self.get_random_style()
        else:
            style = style_info
            style_text = get_style(**style_info)

        return (
            f"{system_message} Follow these phrasing instructions: {style_text}",
            style,
        )

import random

from routellm.dataset.verbalization.styles import get_style
from routellm.dataset.verbalization.tasks import BaseTask


class ShortDescriptionTask(BaseTask):
    NAME = "llm-tasks.short-description"
    VERSION = 6
    TASK_LIST = [
        "Briefly describe the following route in up to 5 sentences:",
        "Give a brief description of the following route:",
        "Please summarize the route in a few sentences.",
        "Can you provide a concise overview of this route?",
        "Can you please briefly describe this route?",
        "I'm interested in a brief description of this route:",
    ]

    def get_task(self):
        return random.choice(ShortDescriptionTask.TASK_LIST)

    def get_system_message(self, style_info=None):
        system_message = "You are an AI that answers questions about routes. Take a deep breath and do it step by step. Use a maximum of 5 sentences."

        if style_info is None:
            style_text, style = self.get_random_style()
        else:
            style = style_info
            style_text = get_style(**style_info)

        return (
            f"{system_message} Follow these phrasing instructions: {style_text}",
            style,
        )

from flask import Flask, request, jsonify
import os
from routellm.controller import Controller
from flask_cors import CORS

app = Flask(__name__)
CORS(app)

port = int(os.environ.get('PORT', 8000))

# Initialize RouteLLM controller (no need to set os.environ manually)
client = Controller(
    routers=["mf"],
    strong_model="gpt-4-1106-preview",
    weak_model="anyscale/Mixtral-8x7B-Instruct-v0.1",
)

@app.route('/route', methods=['POST'])
def route_llm():
    # Authentication
    auth_header = request.headers.get('Authorization')
    if not auth_header or not auth_header.startswith('Bearer '):
        return jsonify({"error": "Unauthorized"}), 401
    token = auth_header.split(' ')[1]
    if token != os.environ.get('SECRET_KEY'):
        return jsonify({"error": "Invalid API key"}), 401

    # Process request
    data = request.json
    messages = data.get('messages', [])

    # Get RouteLLM response
    response = client.chat.completions.create(
        model="router-mf-0.11593",
        messages=messages
    )

    # Format response
    return jsonify({
        "choices": [{
            "message": {
                "role": "assistant",
                "content": response.choices[0].message.content
            }
        }],
        "used_model": response.model  # Adjust if RouteLLM uses a different key
    })

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=port)

import os
import requests
from routellm import RouteLLMController

class ResponseGenerator:
    def __init__(self):
        # Initialize RouteLLM controller
        self.controller = RouteLLMController(
            router="gpt-3.5-turbo",
            models=["gpt-3.5-turbo", "gpt-4"],
            api_key=os.environ.get('ROUTELLM_API_KEY')
        )
        # Initialize ollama API endpoint
        self.ollama_api_url = "http://localhost:11434/api/generate"

    def generate_response(self, threat_level):
        # Generate a response based on the threat level using RouteLLM
        prompt = self._create_prompt(threat_level)
        response = self.controller.chat.completions.create(
            model="router:0.01",  # Use router with 0.01 cost threshold
            messages=[{"role": "system", "content": "You are an AI assistant for threat assessment and response generation."},
                      {"role": "user", "content": prompt}]
        )
        return response.choices[0].message.content

    def generate_response_ollama(self, threat_level):
        # Generate a response based on the threat level using ollama
        prompt = self._create_prompt(threat_level)
        payload = {
            "model": "llama3.1",
            "prompt": prompt
        }
        response = requests.post(self.ollama_api_url, json=payload)
        if response.status_code == 200:
            return response.json()['response']
        else:
            return f"Error: Unable to generate response. Status code: {response.status_code}"

    def _create_prompt(self, threat_level):
        if threat_level < 0.3:
            return "Generate a response for a low threat level situation."
        elif threat_level < 0.7:
            return "Generate a response for a moderate threat level situation."
        else:
            return "Generate a response for a high threat level situation."

import os

import torch
import yaml
from transformers import AutoModelForCausalLM, AutoTokenizer

from routellm.routers.causal_llm.configs import (
    PROMPT_FORMAT_CONFIGS,
    ModelTypeEnum,
    RouterModelConfig,
)
from routellm.routers.causal_llm.prompt_format import PromptFormat


def load_model_config(yaml_path: str):
    with open(yaml_path, "r") as file:
        yaml_data = yaml.safe_load(file)

    return RouterModelConfig(**yaml_data)


def load_prompt_format(model_id):
    prompt_format_dict = PROMPT_FORMAT_CONFIGS[model_id]
    return PromptFormat(**prompt_format_dict, is_generation=True)


def get_model(config: RouterModelConfig, model_ckpt: str, pad_token_id: int = 2):
    if config.model_type == ModelTypeEnum.CAUSAL:
        return AutoModelForCausalLM.from_pretrained(
            model_ckpt,
            trust_remote_code=True,
            torch_dtype=torch.bfloat16,
            use_cache=False,
            attn_implementation=(
                "flash_attention_2" if config.flash_attention_2 else None
            ),
            attention_dropout=config.attention_dropout,
            token=os.getenv("LLAMA2_HF_TOKEN"),
        )
    else:
        raise NotImplementedError(
            f"ModelType {config.model_type} is not implemented yet!"
        )


def get_tokenizer(
    model_id, special_tokens=None, truncation_side="left", padding_side="left"
):
    # Context for legacy=True: https://github.com/huggingface/transformers/issues/25176
    tokenizer = AutoTokenizer.from_pretrained(
        model_id,
        legacy=True,
        truncation_side=truncation_side,
        padding_side=padding_side,
        token=os.getenv("LLAMA2_HF_TOKEN"),
    )
    tokenizer.pad_token = tokenizer.eos_token
    if special_tokens:
        tokenizer.add_tokens(special_tokens, special_tokens=True)
    return tokenizer


def to_openai_api_messages(system_message, classifier_message, messages):
    """Convert the conversation to OpenAI chat completion format."""

    ret = [{"role": "system", "content": system_message}]
    for i, turn in enumerate(messages):
        if i % 2 == 0:
            ret.append(
                {"role": "user", "content": classifier_message.format(question=turn)}
            )
        else:
            ret.append({"role": "assistant", "content": turn})
    return ret

